package com.cartalaap.garage;
import java.time.Instant;import java.util.ArrayList;import java.util.List;import com.cartalaap.user.User;import jakarta.persistence.CascadeType;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.EnumType;import jakarta.persistence.Enumerated;import jakarta.persistence.FetchType;import jakarta.persistence.GeneratedValue;import jakarta.persistence.GenerationType;import jakarta.persistence.Id;import jakarta.persistence.JoinColumn;import jakarta.persistence.ManyToOne;import jakarta.persistence.OneToMany;import jakarta.persistence.OrderBy;import jakarta.persistence.PrePersist;import jakarta.persistence.PreUpdate;import jakarta.persistence.Table;
@Entity@Table(name="garage_vehicles")public class GarageVehicle{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="owner_id")private User owner;@Enumerated(EnumType.STRING)@Column(name="vehicle_type")private VehicleType vehicleType;@Enumerated(EnumType.STRING)@Column(name="garage_status")private GarageStatus status;@Column(nullable=false,length=80)private String brand;@Column(nullable=false,length=80)private String model;@Column(name="manufacture_year")private Integer year;@Column(name="variant_name",length=100)private String variant;@Column(name="fuel_type",length=30)private String fuelType;@Column(length=3000)private String modifications;@Column(name="ownership_story",length=5000)private String ownershipStory;@OneToMany(mappedBy="vehicle",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("sortOrder ASC")private List<GarageVehicleImage>images=new ArrayList<>();@Column(name="created_at")private Instant createdAt;@Column(name="updated_at")private Instant updatedAt;protected GarageVehicle(){}public GarageVehicle(User owner,GarageVehicleRequest r){this.owner=owner;apply(r);}public void update(GarageVehicleRequest r){apply(r);}private void apply(GarageVehicleRequest r){vehicleType=r.vehicleType();status=r.status();brand=r.brand().trim();model=r.model().trim();year=r.year();variant=clean(r.variant());fuelType=clean(r.fuelType());modifications=clean(r.modifications());ownershipStory=clean(r.ownershipStory());images.clear();for(int i=0;i<r.imageUrls().size();i++)images.add(new GarageVehicleImage(this,r.imageUrls().get(i),i));}private String clean(String s){return s==null||s.isBlank()?null:s.trim();}@PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;}@PreUpdate void updateTime(){updatedAt=Instant.now();}public Long getId(){return id;}public User getOwner(){return owner;}public VehicleType getVehicleType(){return vehicleType;}public GarageStatus getStatus(){return status;}public String getBrand(){return brand;}public String getModel(){return model;}public Integer getYear(){return year;}public String getVariant(){return variant;}public String getFuelType(){return fuelType;}public String getModifications(){return modifications;}public String getOwnershipStory(){return ownershipStory;}public List<GarageVehicleImage>getImages(){return images;}public Instant getCreatedAt(){return createdAt;}}
